44	// Resolve `path` to an absolute path. Returns the resolved string on success;
45	// on failure prints an error tagged with `ctx` and returns "".
46	std::string abs_elf(const std::string& path, const std::string& ctx) {
47	  std::error_code ec;
48	  std::string abs = fs::absolute(path, ec).string();
49	  if (ec) {
50	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
51	                 ctx.c_str(), path.c_str());
52	    return "";
53	  }
54	  return abs;
55	}
