57	// Validate the lone-ELF positional shape the standalone models require: print
58	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
59	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
60	// spawns a --describe subprocess per Verilator build). `model` labels the error.
61	int check_one_elf(const Cli& cli, const char* model) {
62	  if (cli.positional.empty()) {
63	    std::fprintf(stderr,
64	                 "andesim run --mode %s: missing ELF (the workload to run; "
65	                 "e.g. a tests/fixtures/<name>.elf)\n",
66	                 model);
67	    return 2;
68	  }
69	  if (cli.positional.size() > 1) {
70	    std::fprintf(stderr,
71	                 "andesim run --mode %s: unexpected argument '%s' "
72	                 "(engine args go after --)\n",
73	                 model, cli.positional[1].c_str());
74	    return 2;
75	  }
76	  return 0;
77	}
78	
79	// Reject an ELF whose class width (rv32/rv64) does not match the engine it would
80	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
81	// from deep inside the engine. Both directions. Returns "" when they agree, when
82	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
83	// declares no xlen (cannot judge). Shared by cycle and hybrid: one wording.
84	std::string elf_engine_arch_error(const std::string& elf,
85	                                  const EngineDescriptor& eng) {
86	  const int ex = elf_xlen(elf);
87	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
88	  char buf[256];
89	  std::snprintf(buf, sizeof(buf),
90	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
91	                "or an rv%d ELF",
92	                ex, eng.id.c_str(), eng.xlen, ex);
93	  return buf;
94	}
