96	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
97	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
98	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
99	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
100	// reports the plan, it does not run it.
101	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
102	                  const std::vector<std::string>& labels) {
103	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
104	  for (size_t i = 0; i < argvs.size(); ++i) {
105	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
106	                labels[i].c_str());
107	    std::printf("%s\n", render_argv(argvs[i]).c_str());
108	  }
109	  return 0;
110	}
111	
112	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
113	// single ELF, then exec the resolved engine standalone with `extra` (model
114	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
115	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
116	// per-model differences -- which engine, and how it is selected -- are resolved
117	// by the caller; `model` here only labels the positional diagnostics.
118	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
119	                   const char* model,
120	                   const std::vector<std::string>& extra = {}) {
121	  if (int rc = check_one_elf(cli, model)) return rc;
122	  // QEMU's -bios flag searches its data directory for relative paths rather
123	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
124	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
125	  if (elf.empty()) return 2;
126	  std::vector<std::string> args = extra;
127	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
128	  std::string err;
129	  // --dry-run: print the exact engine command and stop, spawning nothing. Built
130	  // from the same passthrough_argv run_passthrough would exec, so the preview is
131	  // faithful (the full qemu/vsim command, incl. -bios <elf> and any post-`--`).
132	  if (cli.dry_run) {
133	    const std::vector<std::string> argv =
134	        passthrough_argv(eng, "standalone", elf, args, err);
135	    if (!err.empty()) {
136	      std::fprintf(stderr, "andesim run: %s\n", err.c_str());
137	      return 2;
138	    }
139	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
140	  }
141	  int rc = run_passthrough(eng, "standalone", elf, args, err);
142	  if (!err.empty()) std::fprintf(stderr, "andesim run: %s\n", err.c_str());
143	  return rc;
144	}
145	
146	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
147	// only the built-in qemu descriptor, so it resolves that directly rather than
148	// discover_engines(), which would spawn a --describe subprocess per Verilator
149	// build only to discard them all here.
150	int run_fast(const Cli& cli) {
151	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
152	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
153	    std::fprintf(stderr,
154	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
155	                 "got '%s'\n",
156	                 cli.engine.c_str());
157	    return 2;
158	  }
159	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
160	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
161	  std::string err;
162	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
163	  if (!err.empty()) {
164	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
165	    return 2;
166	  }
167	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
168	  if (cli.gdb) {
169	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
170	    extra.push_back("-gdb");
171	    extra.push_back("tcp::" + port);
172	    extra.push_back("-S");
173	  }
174	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
175	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
176	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
177	  // ELF -- the override is the user's call.
178	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
179	  int xlen = 64;
180	  if (cli.engine == kQemuId32) xlen = 32;
181	  else if (cli.engine == kQemuId64) xlen = 64;
182	  else if (elf_w) xlen = elf_w;  // no explicit engine: follow the ELF
183	  if (!cli.engine.empty() && elf_w && elf_w != xlen)
184	    std::fprintf(stderr,
185	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
186	                 "(running as rv%d)\n",
187	                 cli.engine.c_str(), xlen, elf_w, xlen);
188	  return run_standalone(cli, builtin_qemu_arch(xlen), "fast", extra);
189	}
