191	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
192	// its --jtag-port only after it has reset and halted the hart, so the debugger we
193	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
194	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
195	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
196	// single debugger slot). Returns false on timeout.
197	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
198	  constexpr int kPollMs = 50;
199	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
200	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
201	      char line[512];
202	      while (std::fgets(line, sizeof line, f)) {
203	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
204	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
205	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
206	        unsigned lport = 0, st = 0;
207	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
208	            && st == 0x0A && lport == port) {
209	          std::fclose(f);
210	          return true;
211	        }
212	      }
213	      std::fclose(f);
214	    }
215	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
216	  }
217	  return false;
218	}
