220	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
221	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
222	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
223	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
224	  const char* iceman = std::getenv("ICEMAN");
225	  if (!iceman || !*iceman) {
226	    std::fprintf(stderr,
227	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
228	                 "(export ICEMAN=<path to ICEman binary>)\n");
229	    return 2;
230	  }
231	  // Build vsim argv from the standalone template, appending user passthrough
232	  // and the JTAG port flag.
233	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
234	  if (elf.empty()) return 2;
235	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
236	  std::vector<std::string> vsim_pass = cli.passthrough;
237	  vsim_pass.push_back("--jtag-port");
238	  vsim_pass.push_back(jtag_port);
239	  std::string err;
240	  const std::vector<std::string> vsim_argv =
241	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
242	  if (!err.empty()) {
243	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
244	    return 2;
245	  }
246	  std::fprintf(stderr,
247	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
248	               jtag_port.c_str());
249	  if (fork_background(vsim_argv) < 0) {
250	    std::fprintf(stderr,
251	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
252	    return 1;
253	  }
254	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
255	  // Wait for the port to be LISTENing before launching the debugger (it does not
256	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
257	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
258	  // but launch anyway if it never appears.
259	  if (const int pnum = std::atoi(jtag_port.c_str());
260	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
261	    std::fprintf(stderr,
262	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
263	                 "after 20s; launching the debugger anyway\n",
264	                 jtag_port.c_str());
265	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
266	  // localhost, port 9104) instead of its default real-hardware adapter; without
267	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
268	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
269	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
270	}
271	
272	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
273	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
274	// engine's own output. Unlike fast, this must discover the Verilator build(s)
275	// to resolve the engine (explicit --engine, else the sole one).
276	int run_accurate(const Cli& cli) {
277	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
278	  // --describe subprocess per Verilator build only to fail on the argument.
279	  if (int rc = check_one_elf(cli, "cycle")) return rc;
280	  // --mem-size is validated but has nothing to size: the cycle engine always
281	  // models its full DRAM window. Say so instead of silently ignoring it.
282	  if (!cli.mem_size.empty()) {
283	    std::string se;
284	    if (parse_size(cli.mem_size, se); !se.empty()) {
285	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
286	                   se.c_str());
287	      return 2;
288	    }
289	    std::fprintf(stderr,
290	                 "[andesim] --mem-size: the cycle engine models its full "
291	                 "DRAM window; nothing to size\n");
292	  }
293	  Discovery disc = discover_engines();
294	  std::string err;
295	  const EngineDescriptor* eng =
296	      resolve_accurate_engine(disc.engines, cli.engine, err);
297	  if (!eng) {
298	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
299	    // Surface why an expected engine may be absent (failed --describe, etc.).
300	    for (const std::string& w : disc.warnings)
301	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
302	    return 2;
303	  }
304	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
305	  // vice versa) cannot run. Catch it here with a clear message instead of the
306	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
307	  // positional.
308	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
309	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
310	    return 2;
311	  }
312	  // --dry-run previews the standalone command and spawns nothing, so it takes
313	  // precedence over the interactive --gdb path (a dry run launches no debugger).
314	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
315	  return run_standalone(cli, *eng, "cycle");
316	}
317	
318	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
319	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
320	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
321	// driver's tests/e2e.sh delegation with a single window-cycle line.
322	int run_hybrid(const Cli& cli) {
323	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
324	  auto fail = [](const std::string& msg) {
325	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
326	    return 2;
327	  };
328	
329	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
330	
331	  // Resolve to an absolute, existing path: a clean error beats a downstream
332	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
333	  std::error_code ec;
334	  const fs::path elf = fs::absolute(cli.positional[0], ec);
335	  if (ec || !fs::is_regular_file(elf, ec))
336	    return fail("ELF not found: " + cli.positional[0]);
337	  const std::string elf_path = elf.string();
338	
339	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
340	  // mistake fails fast without spawning a --describe per Verilator build.
341	  std::string err;
342	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
343	  if (!err.empty()) return fail(err);
344	
345	  // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
346	  // hybrid triggers; unknown returned an error above) -- exactly the entry
347	  // boundary --verify needs the oracle to arm on.
348	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
349	  if (!err.empty()) return fail(err);
350	
351	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
352	  if (!cli.mem_size.empty()) {
353	    std::string se;
354	    mem = parse_size(cli.mem_size, se);
355	    if (!se.empty()) return fail("--mem-size: " + se);
356	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
357	    // guest RAM here. The physical mmap reserves one V-scratch page above the
358	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
359	    // page. Failing now beats allocating a huge mmap file first and letting
360	    // QEMU die late.
361	    if (mem > max_program_mem_bytes())
362	      return fail("--mem-size " + cli.mem_size +
363	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
364	                  "reservation)");
365	  }
366	
367	  // L26/F3: refuse a run whose static image would extend into the reserved
368	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
369	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
370	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
371	  // scratch -> silent corruption. Derive the page's start from
372	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
373	  // `mem`, so the threshold tracks the reservation shape instead of relying on
374	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
375	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
376	  // reports it.
377	  {
378	    std::string e;
379	    const uint64_t top = elf_load_top(elf_path, e);
380	    const uint64_t scratch_gpa =
381	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
382	    if (e.empty() && top > scratch_gpa) {
383	      char msg[256];
384	      std::snprintf(msg, sizeof(msg),
385	                    "ELF static image ends at 0x%llx, overlapping the reserved "
386	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
387	                    "; raise --mem-size or shrink the image",
388	                    static_cast<unsigned long long>(top),
389	                    static_cast<unsigned long long>(scratch_gpa));
390	      return fail(msg);
391	    }
392	  }
393	
394	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
395	  // or the sole cycle-accurate engine (reusing the F8 selector).
396	  Discovery disc = discover_engines();
397	  const EngineDescriptor* acc =
398	      resolve_accurate_engine(disc.engines, cli.engine, err);
399	  if (!acc) {
400	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
401	    for (const std::string& w : disc.warnings)
402	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
403	    return 2;
404	  }
405	
406	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
407	  // cannot share architectural state with the rv64 fast leg).
408	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
409	  // ...and the ELF must match that engine width too (same guard as cycle).
410	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
411	    return fail(e);
412	
413	  Plan plan;
414	  plan.elf = elf_path;
415	  plan.mem_size = mem;
416	  Step qemu_step{kQemuId64, "fast-leg", trig};
417	  Step vsim_step{acc->id, "accurate-leg", trig};
418	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
419	  plan.steps = {qemu_step, vsim_step};
420	
421	  // Banner to stderr so the window-cycle result stands alone on stdout.
422	  // vlen is the synced value the fast leg inherits from the engine.
423	  std::fprintf(stderr,
424	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
425	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
426	               elf.stem().string().c_str());
427	
428	  PlanOptions opts;
429	  opts.dry_run = cli.dry_run;
430	  const PlanResult r = run_plan(plan, disc.engines, opts);
431	  if (!r.ok()) {
432	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
433	    return 1;
434	  }
435	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
436	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
437	  // then the vsim accurate leg -- and stop. Nothing was spawned.
438	  if (cli.dry_run) {
439	    std::vector<std::string> labels;
440	    labels.reserve(plan.steps.size());
441	    for (const Step& s : plan.steps)
442	      labels.push_back(s.role + " [" + s.engine_id + "]");
443	    return print_dry_run(r.argvs, labels);
444	  }
445	  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
446	  // output, then anything the ROI wrote on vsim) belong to the user.
447	  for (const PhaseResult& p : r.phases)
448	    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
449	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
450	  // vsim mcycle delta.
451	  {
452	    const unsigned long long q_mc = r.phases[0].mcycle;
453	    const unsigned long long v_mc = r.phases[1].mcycle;
454	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
455	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
456	  }
457	
458	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
459	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
460	  // halt pc, and diff the two drains in-process. The oracle plan gets its
461	  // own fresh mmap: reusing the main run's would boot the oracle on the
462	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
463	  // output was already relayed from the main run.
464	  if (cli.verify) {
465	    char pcbuf[32];
466	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
467	                  static_cast<unsigned long long>(r.phases[1].st.pc));
468	    Trigger vtrig;
469	    vtrig.kind = "verify-" + trig.kind;
470	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
471	    vtrig.params["drain_pc"] = pcbuf;
472	
473	    Plan vplan;
474	    vplan.elf = elf_path;
475	    vplan.mem_size = mem;
476	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
477	
478	    std::fprintf(stderr,
479	                 "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
480	                 "exit, pc=%s)\n",
481	                 pcbuf);
482	    const PlanResult vr = run_plan(vplan, disc.engines);
483	    if (!vr.ok()) {
484	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
485	      return 1;
486	    }
487	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
488	    // engine does not implement (it never restored/re-read them; comparing
489	    // would false-diff). Mirrors the resume/drain gating in vsim.
490	    const DiffReport d =
491	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
492	    print_diff_report(d);
493	    if (!d.ok()) {
494	      std::fprintf(stderr,
495	                   "andesim run --verify: vsim drain diverges from the "
496	                   "QEMU oracle\n");
497	      return 1;
498	    }
499	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
500	  }
501	
502	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
503	              elf.stem().string().c_str());
504	  return 0;
505	}
506	
507	}  // namespace
508	
509	int cmd_run(const Cli& cli) {
510	  if (cli.model.empty()) {
511	    std::fprintf(stderr,
512	                 "andesim run: --mode fast|cycle|hybrid is required "
513	                 "(pick the composition; see 'andesim run --help')\n");
514	    return 2;
515	  }
516	  if (!find_model(cli.model)) {
517	    std::fprintf(stderr,
518	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
519	                 cli.model.c_str());
520	    return 2;
521	  }
522	  if (!cli.gdb_port.empty() && !cli.gdb) {
523	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
524	    return 2;
525	  }
526	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
527	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
528	  if (cli.gdb && cli.model == "hybrid") {
529	    std::fprintf(stderr,
530	                 "andesim run: --gdb is not supported with --mode hybrid\n");
531	    return 2;
532	  }
533	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
534	  // composition has a second engine to check.
535	  if (cli.verify && cli.model != "hybrid") {
536	    std::fprintf(stderr,
537	                 "andesim run: --verify requires --mode hybrid (the %s "
538	                 "model has nothing to cross-check)\n",
539	                 cli.model.c_str());
540	    return 2;
541	  }
542	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window; fast and
543	  // cycle run the whole program and would silently drop them, handing back a
544	  // whole-program figure for the window the user asked for. Reject instead.
545	  if (!cli.trigger.empty() && cli.model != "hybrid") {
546	    std::fprintf(stderr,
547	                 "andesim run: --trigger applies only to --mode hybrid "
548	                 "(the ROI delimiter); fast/cycle run the whole program\n");
549	    return 2;
550	  }
551	  if (!cli.pc_end.empty() && cli.model != "hybrid") {
552	    std::fprintf(stderr,
553	                 "andesim run: --pc-end applies only to --mode hybrid "
554	                 "--trigger pc\n");
555	    return 2;
556	  }
557	  if (!cli.pc_start.empty() && cli.model != "hybrid") {
558	    std::fprintf(stderr,
559	                 "andesim run: --pc-start applies only to --mode hybrid "
560	                 "--trigger pc\n");
561	    return 2;
562	  }
563	  if (cli.model == "fast") return run_fast(cli);
564	  if (cli.model == "cycle") return run_accurate(cli);
565	  return run_hybrid(cli);  // model validated above; only hybrid remains
566	}
567	
568	}  // namespace andes_sim
