1	/* vplat: one newlib syscall layer that works on EVERY engine.
2	 *
3	 * Replaces -lgloss_vh (semihosting) so a single ELF runs unmodified on
4	 * QEMU (fast), vsim (cycle) and across a hybrid handoff. It only touches
5	 * channels both engines model at the same addresses:
6	 *
7	 *   stdio (fd 0-2)  ATCUART100 UART2: THR @0xf0300020, LSR @0xf0300034.
8	 *                   QEMU: serial_mm_init(UART2+0x20, shift 2) = serial_hd(0);
9	 *                   vsim: verilator/src/platform/uart.hpp -> host stdout.
10	 *   exit            SimControl @0xe0080000: u32 exit code (<256).
11	 *                   vsim: sim_control.hpp; QEMU: hw/misc/andes_sim_control.c.
12	 *   file io (fd>2)  HTIF magicmem command @0xe0080010, served host-side
13	 *                   (vsim: sim_control.hpp syscall table; QEMU: same device).
14	 *
15	 * No semihosting, no ecall, and no "which engine am I on" probe -- hybrid
16	 * migrates the running process between engines, so any boot-time detection
17	 * would go stale at the handoff. Every call must be engine-blind.
18	 */
19	
20	#include <stdint.h>
21	#include <stddef.h>
22	#include <sys/stat.h>
23	#include <unistd.h>
24	
25	/* ---- UART2 (console) ------------------------------------------------- */
26	
27	#define UART_THR (*(volatile uint32_t*) 0xf0300020UL)
28	#define UART_LSR (*(volatile uint32_t*) 0xf0300034UL)
29	#define UART_LSR_THRE 0x20u
30	
31	static void uart_putc(char c)
32	{
33	  while (!(UART_LSR & UART_LSR_THRE))
34	    ;
35	  UART_THR = (uint32_t) (unsigned char) c;
36	}
37	
38	/* ---- SimControl / HTIF ------------------------------------------------ */
39	
40	#define SIM_EXIT_ADDR   0xe0080000UL
41	#define HTIF_TOHOST_CMD 0xe0080010UL
42	
43	/* HTIF syscall numbers -- must match the table in
44	 * verilator/src/platform/sim_control.hpp (and the QEMU mirror device). */
45	#define VH_SYS_GETTIMEOFDAY 5
46	#define VH_SYS_OPEN         6
47	#define VH_SYS_WRITE        7
48	#define VH_SYS_GETCWD       8
49	#define VH_SYS_LSEEK        9
50	#define VH_SYS_READ         10
51	#define VH_SYS_FLEN         11
52	#define VH_SYS_CLOSE        12
53	#define VH_SYS_ACCESS       13
54	#define VH_SYS_FACCESSAT    14
55	#define VH_SYS_FSTAT        15
56	#define VH_SYS_FSTATAT      16
57	#define VH_SYS_LINK         17
58	#define VH_SYS_LSTAT        18
59	#define VH_SYS_STAT         19
60	#define VH_SYS_OPENAT       20
61	#define VH_SYS_RENAME       21
62	#define VH_SYS_UNLINK       22
63	
64	static uint64_t magicmem[8] __attribute__((aligned(64)));
65	
66	/* The host (SimControl) reads magicmem straight from RAM, behind the
67	 * hart's caches, so write back L1 (and L2 if present) before handing the
68	 * command over. CCTL command 6 = L1D_WBINVAL_ALL, 0x12 = L2_WBINVAL_ALL.
69	 * On QEMU the CSR write is accepted and memory is coherent anyway. */
70	static void flush_dcache(void)
71	{
72	  __asm__ __volatile__("csrw mcctlcommand, %0" ::"rK"(6));
73	#if __riscv_xlen == 64
74	  /* L2 writeback. The L2C control/CCTL registers are 64-bit MMIO and the L2
75	   * "present" flag is mmsc_cfg bit 46, so this whole block is rv64-only. The
76	   * rv32 cores here (d23) have no L2 and rely on the L1 writeback above. */
77	  __asm__ __volatile__(
78	    "csrr    t0, mmsc_cfg\n"
79	    "li      t1, 1\n"
80	    "slli    t1, t1, 46\n"
81	    "and     t2, t0, t1\n"
82	    "beqz    t2, 1f\n"
83	    "li      t3, 0xe0500008\n"   /* L2C_REG_CTL: enabled? */
84	    "ld      t4, 0(t3)\n"
85	    "andi    t4, t4, 1\n"
86	    "beqz    t4, 1f\n"
87	    "li      t5, 0xe0500040\n"   /* L2C_REG_CCTL <- WBINVAL_ALL */
88	    "li      t6, 0x12\n"
89	    "sd      t6, 0(t5)\n"
90	    "2:\n"
91	    "li      t2, 0xe0500080\n"   /* poll L2C_REG_CCTL_M0_ST until idle */
92	    "ld      t3, 0(t2)\n"
93	    "andi    t3, t3, 0xF\n"
94	    "li      t5, 1\n"
95	    "beq     t3, t5, 2b\n"
96	    "1:\n" ::: "t0", "t1", "t2", "t3", "t4", "t5", "t6", "memory");
97	#endif
98	}
99	
100	static intptr_t htif_syscall(uint64_t n, uintptr_t a0, uintptr_t a1,
101	                             uintptr_t a2, uintptr_t a3)
102	{
103	  magicmem[0] = n;
104	  magicmem[1] = a0;
105	  magicmem[2] = a1;
106	  magicmem[3] = a2;
107	  magicmem[4] = a3;
108	  magicmem[5] = 0;
109	  magicmem[6] = 0;
110	  magicmem[7] = 0;
111	  flush_dcache();
112	  *(volatile uint64_t*) HTIF_TOHOST_CMD = (uintptr_t) magicmem;
113	  __asm__ __volatile__("fence rw,rw" ::: "memory");
114	  return (intptr_t) magicmem[0];
115	}
116	
117	/* ---- newlib stubs ------------------------------------------------------ */
118	
119	__attribute__((used)) ssize_t _write(int fd, const void* ptr, size_t len)
120	{
121	  if (fd > 2)
122	    return htif_syscall(VH_SYS_WRITE, fd, (uintptr_t) ptr, len, 0);
123	  for (size_t i = 0; i < len; ++i)
124	    uart_putc(((const char*) ptr)[i]);
125	  return (ssize_t) len;
126	}
127	
128	__attribute__((used)) ssize_t _read(int fd, void* buf, size_t len)
129	{
130	  if (fd > 2)
131	    return htif_syscall(VH_SYS_READ, fd, (uintptr_t) buf, len, 0);
132	  return 0; /* no console input on either engine: EOF */
133	}
134	
135	__attribute__((used)) int _fstat(int fd, struct stat* st)
136	{
137	  if (fd > 2)
138	    return (int) htif_syscall(VH_SYS_FSTAT, fd, (uintptr_t) st, 0, 0);
139	  st->st_mode = S_IFCHR; /* char device -> newlib line-buffers stdout */
140	  return 0;
141	}
142	
143	__attribute__((used)) int _isatty(int fd) { return fd <= 2; }
144	
145	__attribute__((used)) int _close(int fd)
146	{
147	  if (fd > 2)
148	    return (int) htif_syscall(VH_SYS_CLOSE, fd, 0, 0, 0);
149	  return 0;
150	}
151	
152	__attribute__((used)) off_t _lseek(int fd, off_t offset, int dir)
153	{
154	  if (fd > 2)
155	    return htif_syscall(VH_SYS_LSEEK, fd, offset, dir, 0);
156	  return 0;
157	}
158	
159	__attribute__((used)) int _open(const char* name, int flags, int mode, ...)
160	{
161	  return (int) htif_syscall(VH_SYS_OPEN, (uintptr_t) name, flags, mode, 0);
162	}
163	
164	__attribute__((used)) int _openat(int dirfd, const char* name, int flags, ...)
165	{
166	  return (int) htif_syscall(VH_SYS_OPENAT, dirfd, (uintptr_t) name, flags, 0);
167	}
168	
169	__attribute__((used)) int _stat(const char* file, struct stat* st)
170	{
171	  return (int) htif_syscall(VH_SYS_STAT, (uintptr_t) file, (uintptr_t) st, 0, 0);
